// Shared shopping list API. Pure Node stdlib + node:sqlite (Node >= 22.5).
const http = require('node:http');
const path = require('node:path');
const fs = require('node:fs');
const crypto = require('node:crypto');

let DatabaseSync;
try {
  ({ DatabaseSync } = require('node:sqlite'));
} catch (e) {
  console.error('node:sqlite unavailable:', e.message);
  process.exit(1);
}

const PORT = parseInt(process.env.PORT || '3000', 10);
const DATA_DIR = process.env.DATA_DIR || '/data';
fs.mkdirSync(DATA_DIR, { recursive: true });
const DB_PATH = path.join(DATA_DIR, 'shopping.db');
const db = new DatabaseSync(DB_PATH);
db.exec(`
  PRAGMA journal_mode = WAL;
  PRAGMA busy_timeout = 5000;
  CREATE TABLE IF NOT EXISTS items (
    seq    INTEGER PRIMARY KEY AUTOINCREMENT,
    id     TEXT NOT NULL UNIQUE,
    text   TEXT NOT NULL,
    bought INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL
  );
`);

const qItems = db.prepare('SELECT id, text, bought FROM items ORDER BY seq ASC');
const qItem = db.prepare('SELECT id, text, bought FROM items WHERE id = ?');
const qInsert = db.prepare('INSERT INTO items (id, text, bought, created_at) VALUES (?, ?, 0, ?)');
const qUpdate = db.prepare('UPDATE items SET text = ?, bought = ? WHERE id = ?');
const qDelete = db.prepare('DELETE FROM items WHERE id = ?');

const toItem = (r) => r && { id: r.id, text: r.text, bought: !!r.bought };
const now = () => new Date().toISOString();

function send(res, status, body) {
  const headers = {
    'Content-Type': 'application/json; charset=utf-8',
    'Cache-Control': 'no-store',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PATCH, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
  };
  if (status === 204 || body === undefined) {
    res.writeHead(status, headers);
    res.end();
    return;
  }
  const payload = JSON.stringify(body);
  headers['Content-Length'] = Buffer.byteLength(payload);
  res.writeHead(status, headers);
  res.end(payload);
}
const err = (res, status, msg) => send(res, status, { error: msg });

function readJson(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    let tooBig = false;
    req.on('data', (c) => {
      if (tooBig) return;
      data += c;
      if (data.length > 64 * 1024) { tooBig = true; reject(Object.assign(new Error('payload too large'), { status: 413 })); }
    });
    req.on('end', () => {
      if (tooBig) return;
      if (!data.trim()) { resolve({}); return; }
      try { resolve(JSON.parse(data)); }
      catch { reject(Object.assign(new Error('invalid JSON body'), { status: 400 })); }
    });
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const parts = url.pathname.split('/').filter(Boolean);
  const method = req.method.toUpperCase();
  try {
    if (method === 'OPTIONS') return send(res, 204);

    if (parts[0] === 'health' && parts.length === 1) {
      if (method !== 'GET') return err(res, 405, 'method not allowed');
      return send(res, 200, { ok: true });
    }

    if (parts[0] === 'items' && parts.length === 1) {
      if (method === 'GET') return send(res, 200, qItems.all().map(toItem));
      if (method === 'POST') {
        const body = await readJson(req);
        const text = typeof body.text === 'string' ? body.text.trim() : '';
        if (!text) return err(res, 400, 'text is required');
        const id = crypto.randomUUID();
        qInsert.run(id, text, now());
        return send(res, 201, toItem(qItem.get(id)));
      }
      return err(res, 405, 'method not allowed');
    }

    if (parts[0] === 'items' && parts.length === 2) {
      const id = decodeURIComponent(parts[1]);
      const row = qItem.get(id);
      if (method === 'GET') {
        if (!row) return err(res, 404, 'not found');
        return send(res, 200, toItem(row));
      }
      if (method === 'PATCH' || method === 'PUT') {
        if (!row) return err(res, 404, 'not found');
        const body = await readJson(req);
        let text = row.text;
        let bought = !!row.bought;
        if (body.text !== undefined) {
          if (typeof body.text !== 'string' || !body.text.trim()) return err(res, 400, 'text must be a non-empty string');
          text = body.text.trim();
        }
        if (body.bought !== undefined) {
          if (typeof body.bought !== 'boolean') return err(res, 400, 'bought must be a boolean');
          bought = body.bought;
        }
        qUpdate.run(text, bought ? 1 : 0, id);
        return send(res, 200, toItem(qItem.get(id)));
      }
      if (method === 'DELETE') {
        if (!row) return err(res, 404, 'not found');
        qDelete.run(id);
        return send(res, 204);
      }
      return err(res, 405, 'method not allowed');
    }

    return err(res, 404, 'not found');
  } catch (e) {
    if (e && e.status) return err(res, e.status, e.message);
    console.error('internal error', e);
    return err(res, 500, 'internal error');
  }
});

server.listen(PORT, '0.0.0.0', () => console.log(`api listening on 0.0.0.0:${PORT}, db=${DB_PATH}`));

for (const sig of ['SIGTERM', 'SIGINT']) {
  process.on(sig, () => {
    console.log(`got ${sig}, shutting down`);
    server.close(() => { try { db.close(); } catch {} process.exit(0); });
    setTimeout(() => process.exit(0), 3000).unref();
  });
}
