'use strict';
// End-to-end test of the API against a running server (BASE_URL, default http://127.0.0.1:3000).
const BASE = process.env.BASE_URL || 'http://127.0.0.1:3000';
let failures = 0;
function check(name, cond, extra) {
  if (cond) console.log('ok   - ' + name);
  else { failures++; console.log('FAIL - ' + name + (extra !== undefined ? ' :: ' + JSON.stringify(extra) : '')); }
}
async function req(method, p, body) {
  const r = await fetch(BASE + p, {
    method,
    headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  let json = null;
  const t = await r.text();
  if (t) { try { json = JSON.parse(t); } catch { json = t; } }
  return { status: r.status, json, type: r.headers.get('content-type') || '' };
}

(async () => {
  // Fresh start: clear whatever is there.
  const before = await req('GET', '/items');
  check('GET /items -> 200 array', before.status === 200 && Array.isArray(before.json), before);
  for (const it of before.json || []) await req('DELETE', '/items/' + it.id);

  const h = await req('GET', '/health');
  check('GET /health -> {"ok":true}', h.status === 200 && h.json && h.json.ok === true, h);

  const c1 = await req('POST', '/items', { text: 'milk' });
  check('POST /items -> 201 with item', c1.status === 201 && c1.json.text === 'milk' && c1.json.bought === false && typeof c1.json.id === 'string', c1);
  check('POST response is JSON', c1.type.includes('application/json'), c1.type);
  const c2 = await req('POST', '/items', { text: 'eggs' });
  check('POST second item', c2.status === 201, c2);

  const b1 = await req('POST', '/items', { text: '   ' });
  check('POST blank text -> 400 JSON error', b1.status === 400 && b1.json && typeof b1.json.error === 'string', b1);
  const b2 = await req('POST', '/items', {});
  check('POST missing text -> 400', b2.status === 400, b2);

  const list = await req('GET', '/items');
  check('GET /items ordered oldest first', list.json.map(i => i.text).join(',') === 'milk,eggs', list.json);
  check('items have exactly id,text,bought', list.json.every(i => Object.keys(i).sort().join(',') === 'bought,id,text'), list.json);

  const p1 = await req('PATCH', '/items/' + c1.json.id, { bought: true });
  check('PATCH bought -> 200 true', p1.status === 200 && p1.json.bought === true && p1.json.text === 'milk', p1);
  const p2 = await req('PATCH', '/items/' + c1.json.id, { text: 'oat milk' });
  check('PATCH text keeps bought', p2.status === 200 && p2.json.text === 'oat milk' && p2.json.bought === true, p2);
  const p3 = await req('PATCH', '/items/' + c1.json.id, { bought: false });
  check('PATCH bought false', p3.status === 200 && p3.json.bought === false, p3);
  const p4 = await req('PATCH', '/items/nope-nope', { bought: true });
  check('PATCH unknown -> 404', p4.status === 404 && p4.json && p4.json.error, p4);

  const g = await req('GET', '/items/' + c2.json.id);
  check('GET /items/{id} -> 200', g.status === 200 && g.json.id === c2.json.id, g);

  const del = await req('DELETE', '/items/' + c2.json.id);
  check('DELETE -> 204 empty', del.status === 204 && del.json === null, del);
  const del2 = await req('DELETE', '/items/' + c2.json.id);
  check('DELETE again -> 404', del2.status === 404, del2);

  const nf = await req('GET', '/nope');
  check('unknown path -> 404 JSON', nf.status === 404 && nf.json && nf.json.error, nf);
  const mna = await req('PUT', '/items');
  check('bad method -> 405 JSON', mna.status === 405 && mna.json && mna.json.error, mna);

  // Leave a deterministic fixture behind for the restart-persistence check.
  for (const it of (await req('GET', '/items')).json) await req('DELETE', '/items/' + it.id);
  const keep1 = await req('POST', '/items', { text: 'persist-a' });
  const keep2 = await req('POST', '/items', { text: 'persist-b' });
  await req('PATCH', '/items/' + keep2.json.id, { bought: true });
  console.log('FIXTURE ids ' + keep1.json.id + ' ' + keep2.json.id);

  console.log(failures === 0 ? 'ALL PASS' : failures + ' FAILURES');
  process.exit(failures === 0 ? 0 : 1);
})().catch((e) => { console.error('test crash', e); process.exit(2); });
