'use strict';
// After a restart: items created earlier must still be there, with their bought state.
const BASE = process.env.BASE_URL || 'http://127.0.0.1:3000';
(async () => {
  let failures = 0;
  const r = await fetch(BASE + '/items');
  const items = await r.json();
  const a = items.find((i) => i.text === 'persist-a');
  const b = items.find((i) => i.text === 'persist-b');
  const ok = (n, c) => { console.log((c ? 'ok   - ' : 'FAIL - ') + n); if (!c) failures++; };
  ok('persist-a survived with bought=false', !!a && a.bought === false);
  ok('persist-b survived with bought=true', !!b && b.bought === true);
  ok('ordering kept (persist-a before persist-b)', !!a && !!b && items.indexOf(a) < items.indexOf(b));
  // clean up fixture
  for (const i of [a, b]) if (i) await fetch(BASE + '/items/' + i.id, { method: 'DELETE' });
  console.log(failures === 0 ? 'PERSISTENCE PASS' : failures + ' PERSISTENCE FAILURES');
  process.exit(failures === 0 ? 0 : 1);
})().catch((e) => { console.error(e); process.exit(2); });
